$(function(){$(document).on("click",'[data-btn="open-mobile-menu"]',function(){$(this).toggleClass("flipped"),$('[data-element="mobile-menu"]').toggleClass("opened")});new Swiper(".swiper",{slidesPerView:3,spaceBetween:50,loop:!0,centeredSlides:!0,grabCursor:!0,pagination:{el:".swiper-pagination",type:"bullets"}})});